import {
  capEffect,
  chartAnnotationInk,
  chartAnnotationWash,
  chartAxis,
  chartEffects,
  chartFrame,
  chartLegend,
  chartMarkSource,
  chartState,
  chartTooltip,
  chartTwin,
  FRAME_RECIPES,
} from '../chart-frame'
import { cond, describeMember, each, el, flag, lit, run, type FixtureValue } from '../dsl'

/**
 * The React fixture's data: Relay's, generated by arithmetic, not randomly, so
 * the correlation is the same on every render. Each list is computed here and
 * written into the fixture as plain JSON.
 */
type Row = Record<string, number | string | null>

/** One mark per agent (24): average handle minutes against CSAT, negatively correlated. */
const AGENTS: Row[] = Array.from({ length: 24 }, (_, index) => {
  const minutes = 2 + ((index * 7) % 12) + ((index * 13) % 10) / 10
  const wobble = (((index * 29) % 11) - 5) / 12
  return {
    minutes: Math.round(minutes * 10) / 10,
    csat: Math.round((5.1 - minutes * 0.14 + wobble) * 100) / 100,
  }
})

/** The same measures split by team. Each observation belongs to one series. */
const TEAMS: Row[] = AGENTS.map((row, index) =>
  index % 2 === 0
    ? { minutes: row['minutes'] ?? 0, triage: row['csat'] ?? 0, escalations: null }
    : { minutes: row['minutes'] ?? 0, triage: null, escalations: row['csat'] ?? 0 },
)

/** The third column for bubble mode: tickets handled, 20–160. */
const WITH_LOAD: Row[] = AGENTS.map((row, index) => ({
  ...row,
  tickets: 20 + ((index * 37) % 141),
}))

/** Four series, above the canonical cap of three, for the dev-warning entry. */
const FOUR_TEAMS: Row[] = AGENTS.map((row, index) => {
  const keys = ['triage', 'escalations', 'billing', 'onboarding']
  const mine = keys[index % 4] ?? 'triage'
  return {
    minutes: row['minutes'] ?? 0,
    ...Object.fromEntries(keys.map((key) => [key, key === mine ? (row['csat'] ?? null) : null])),
  }
})

/** A dense plot within the linear scan's intended range: 500 observations, one series. */
const DENSE: Row[] = Array.from({ length: 500 }, (_, index) => {
  const minutes = 1 + ((index * 17) % 130) / 10
  const wobble = (((index * 31) % 23) - 11) / 14
  return {
    minutes: Math.round(minutes * 10) / 10,
    csat: Math.round((5.2 - minutes * 0.12 + wobble) * 100) / 100,
  }
})

/** Deploys across July: date against minutes of incident that followed. */
const DEPLOYS: Row[] = Array.from({ length: 18 }, (_, index) => ({
  date: `2026-07-${String(1 + ((index * 5) % 28)).padStart(2, '0')}`,
  minutes: ((index * 43) % 90) + 4,
}))

const rows = (list: Row[]): FixtureValue => list as FixtureValue

const CSAT_SERIES = [{ key: 'csat', label: 'CSAT' }]

/**
 * ScatterChart (`design/components/scatter-chart.md`): the correlation between
 * two measures, one mark per observation, with mark area encoding a third value
 * in bubble mode. The drawing is the engine's `scatterChartModel`, which the
 * React member draws too: both value axes, the zero rules, every mark's place
 * and radius, and the dev warnings, among them the palette's any-neighbour cap.
 * The readout at a reading position is `scatterChartReadout`, and what
 * `onSelect` reports is `scatterChartSelection`.
 *
 * The cap is read from the plot when the marks appear (`capEffect`), as the
 * React member reads it from its surface, and the model warns when the series
 * exceed it. The plot is one focus stop. The reading position is a mark: Left/Right
 * walk the rows within the active series, and Up/Down switch series at the same
 * row, through the engine's reading machine, whose series coordinate rests at
 * `0` because a mark always belongs to a series. The pointer reads the mark
 * nearest its coordinates on the plane (`nearest2D`) within the minimum hit
 * size, and clears the reading past it. Enter, Space and a click report the
 * selection when the caller listens for `select`. The legend toggles a series
 * out of the marks, and the y domain refits to the rest.
 */
export default describeMember({
  member: 'ScatterChart',
  dir: 'charts',
  recipe: 'charts/scatter-chart',
  recipes: FRAME_RECIPES,
  defaults: {
    size: lit('md'),
    tooltip: '() => ({})',
    loading: 'false',
    messages: '() => DEFAULT_CHART_MESSAGES',
  },
  state: { ...chartState('0'), cap: 'readChartCap(null)' },
  derived: {
    input:
      '({ data, series, x, y, bubble, annotations, label, locale, messages, tooltip, loading, selectable: listening.select, hidden, cap, box })',
    model: 'scatterChartModel(input)',
    view: 'readingView(position, data.length, model.visible.length)',
    readout: 'scatterChartReadout(input, model, view)',
    // The series the reading is on: the walked one, the first before Up/Down moves it.
    walked: 'view.series ?? 0',
    activate:
      "() => { const selection = scatterChartSelection(input, model, reading.now()); if (selection !== null) emit('select', selection) }",
    // A mark always belongs to a series, so the series coordinate rests at 0 and Up/Down walk it.
    walk: '({ count: data.length, seriesCount: model.visible.length, walkSeries: true, seriesStart: 0 })',
    marks: chartMarkSource('scatterChart'),
    onKey:
      "(event: KeyboardEvent) => { if (listening.select && (event.key === 'Enter' || event.key === ' ')) { event.preventDefault(); activate(); return } reading.update(walk); if (reading.key(event.key)) event.preventDefault() }",
    // The nearest mark on the plane within the minimum hit size; past it the pointer is over the surface and the reading clears.
    onPointer:
      '(event: PointerEvent) => { if (model.plot === null) return; const rect = (event.currentTarget as Element).getBoundingClientRect(); const hit = nearest2D(model.points, event.clientX - rect.left, event.clientY - rect.top); if (hit === -1) { reading.clear(); return } reading.moveTo(hit % data.length, Math.floor(hit / data.length)) }',
  },
  effects: [capEffect(), ...chartEffects()],
  // The spec's `agent` fence: the marks a chart with `onSelect` gives (`chartMarkSource`), and the
  // legend's keys, read from the figure (`chartSeries`).
  agent: {
    on: 'frame',
    state: {
      items: 'listening.select ? chartMarks(marks, reading) : []',
      position: 'chartPosition(marks, reading)',
      count: 'walk.count',
      series: 'chartSeries(frame, chartLegend.key, model.painted)',
      hidden: 'chartHiddenSeries(frame, chartLegend.key, model.painted)',
    },
    actions: {
      read: { argument: 'number', run: 'readChartPosition(marks, value, reading)' },
      choose: {
        argument: 'id',
        among: 'items',
        run: 'chooseChartMark(marks, value, reading, activate)',
      },
      toggle: {
        argument: 'id',
        among: 'series',
        run: 'toggleChartSeries(frame, chartLegend.key, model.painted, value)',
      },
    },
    unless: '!listening.select && !model.legend',
  },
  template: chartFrame({
    member: 'ScatterChart',
    state: 'model.state',
    summary: 'model.summary',
    announcement: 'readout.announcement',
    yAxis: [chartAxis('y', 'model.axes?.y')],
    xAxis: [chartAxis('x', 'model.axes?.x')],
    legend: [
      cond('model.legend', [
        chartLegend({
          series: 'model.painted',
          keyShape: 'rect',
          rootClass: 'legend',
          toggles: true,
        }),
      ]),
    ],
    twin: [chartTwin('model.twin.columns', 'model.twin.rows')],
    tooltip: [chartTooltip('readout.tooltip')],
    plot: [
      // One focus stop. Left/Right walk rows within the active series; Up/Down switch series at the same row.
      el(
        'div',
        {
          part: 'surface',
          class: ['surface'],
          attrs: { tabindex: lit('0'), role: lit('img'), 'aria-label': 'label' },
          on: {
            keydown: run('onKey($event)'),
            click: run('activate()'),
            pointermove: run('onPointer($event)'),
            pointerleave: run('reading.clear()'),
            blur: run('reading.clear()'),
          },
        },
        [
          cond('model.plot !== null', [
            el(
              'svg',
              {
                part: 'marks',
                class: ['marks'],
                attrs: {
                  'data-reading': flag('view.active'),
                  width: 'model.plot?.width',
                  height: 'model.plot?.height',
                  'aria-hidden': lit('true'),
                  focusable: lit('false'),
                },
              },
              [
                // Gridlines on both axes, because both are value axes.
                el('g', { part: 'grid', class: ['grid'] }, [
                  each('model.plot?.grid ?? []', 'line', 'line.key', [
                    el('path', { attrs: { d: 'line.d' } }),
                  ]),
                ]),
                // A zero rule per axis whose domain holds zero.
                each('model.plot?.zero ?? []', 'rule', 'rule.key', [
                  el('path', { part: 'zero', class: ['zero'], attrs: { d: 'rule.d' } }),
                ]),
                chartAnnotationWash('model.plot?.wash ?? []'),
                // One group per series: the read mark's series keeps full opacity and the rest fade back.
                el('g', { part: 'points', class: ['points'] }, [
                  each('model.plot?.groups ?? []', 'group', 'group.key', [
                    el(
                      'g',
                      {
                        geometry: { '--pm-chart-mark': 'group.paint' },
                        attrs: { 'data-active': flag('view.active && walked === group.series') },
                      },
                      [
                        each('group.dots', 'dot', 'dot.index', [
                          el('circle', {
                            class: ['dot'],
                            // The per-dot stagger index, which the stylesheet turns into a capped delay.
                            geometry: { '--pm-chart-dot': 'dot.index' },
                            attrs: {
                              cx: 'dot.cx',
                              cy: 'dot.cy',
                              r: 'dot.r',
                              'data-active': flag(
                                'view.index === dot.index && walked === group.series',
                              ),
                            },
                          }),
                        ]),
                      ],
                    ),
                  ]),
                ]),
                chartAnnotationInk('model.plot?.ink ?? null'),
              ],
            ),
          ]),
        ],
      ),
    ],
  }),
  states: [
    {
      name: 'handle time vs CSAT',
      props: {
        data: rows(AGENTS),
        series: CSAT_SERIES,
        x: { key: 'minutes', label: 'Handle minutes' },
        label: 'Handle time against satisfaction',
      },
      expect: { 'data-size': 'md' },
    },
    {
      name: 'two teams',
      props: {
        data: rows(TEAMS),
        series: [
          { key: 'triage', label: 'Triage' },
          { key: 'escalations', label: 'Escalations' },
        ],
        x: { key: 'minutes', label: 'Handle minutes' },
        label: 'Handle time against satisfaction, by team',
      },
    },
    {
      // The sqrt scale between the 8px and 24px bounds: area encodes the load.
      name: 'bubble',
      props: {
        data: rows(WITH_LOAD),
        series: CSAT_SERIES,
        x: { key: 'minutes', label: 'Handle minutes' },
        bubble: { key: 'tickets', label: 'Tickets handled' },
        label: 'Handle time, satisfaction and load',
      },
    },
    {
      // The dev warning names --pm-chart-cap; the plot still draws every series.
      name: 'cap warning',
      props: {
        data: rows(FOUR_TEAMS),
        series: [
          { key: 'triage', label: 'Triage' },
          { key: 'escalations', label: 'Escalations' },
          { key: 'billing', label: 'Billing' },
          { key: 'onboarding', label: 'Onboarding' },
        ],
        x: { key: 'minutes', label: 'Handle minutes' },
        label: 'Four teams — past the cap',
      },
    },
    {
      // The linear scan's intended range: marks stay 8px and the twin holds every row.
      name: 'dense',
      props: {
        data: rows(DENSE),
        series: CSAT_SERIES,
        x: { key: 'minutes', label: 'Handle minutes' },
        label: 'Every conversation this quarter',
      },
    },
    {
      name: 'time x',
      props: {
        data: rows(DEPLOYS),
        series: [{ key: 'minutes', label: 'Incident minutes' }],
        x: { key: 'date', scale: 'time', label: 'Deploy date' },
        label: 'Deploys against incident minutes',
      },
    },
    {
      name: 'annotations',
      props: {
        data: rows(AGENTS),
        series: CSAT_SERIES,
        x: { key: 'minutes', label: 'Handle minutes' },
        annotations: [
          { kind: 'band', from: 4.5, to: 5, label: 'CSAT target' },
          { kind: 'line', value: 4, label: 'Floor' },
        ],
        label: 'Handle time against satisfaction, with the target zone',
      },
    },
    {
      name: 'empty',
      props: {
        data: [],
        series: CSAT_SERIES,
        x: { key: 'minutes' },
        label: 'Handle time against satisfaction',
      },
      expect: { 'data-state': 'empty' },
    },
    {
      name: 'loading',
      props: {
        data: rows(AGENTS),
        series: CSAT_SERIES,
        x: { key: 'minutes' },
        loading: true,
        label: 'Handle time against satisfaction',
      },
      expect: { 'data-state': 'loading' },
    },
    {
      // `false` removes the visual layer only: the reading, its announcements and the twin stay.
      name: 'tooltip off',
      props: {
        data: rows(AGENTS),
        series: CSAT_SERIES,
        x: { key: 'minutes' },
        tooltip: false,
        label: 'Handle time against satisfaction, print',
      },
    },
    {
      // With `onSelect`: the summary names the activation, and an agent can pick a point.
      name: 'selectable',
      props: {
        data: rows(AGENTS),
        series: CSAT_SERIES,
        x: { key: 'minutes', label: 'Handle minutes' },
        label: 'Handle time against satisfaction',
        onSelect: { js: '() => {}' },
      },
    },
  ],
})
